import{_ as n,o as a,c as e,ai as p}from"./chunks/framework.Ba-VnP44.js";const u=JSON.parse('{"title":"通用项目 Rules · v1.0","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/rules.md","filePath":"ai/productivity/dev-spec/rules.md"}'),l={name:"ai/productivity/dev-spec/rules.md"};function i(r,s,t,c,b,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="通用项目-rules-·-v1-0" tabindex="-1">通用项目 Rules · v1.0 <a class="header-anchor" href="#通用项目-rules-·-v1-0" aria-label="Permalink to “通用项目 Rules · v1.0”">​</a></h1><blockquote><p>约束 AI Agent 项目开发行为的通用规则集合，项目初始化时按适用范围选用。</p></blockquote><p><strong>定位：</strong> 约束 AI Agent 在项目开发中的行为，明确技术边界、代码规范、数据安全和操作要求。</p><h2 id="一、rules-目录建议" tabindex="-1">一、Rules 目录建议 <a class="header-anchor" href="#一、rules-目录建议" aria-label="Permalink to “一、Rules 目录建议”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>项目根目录/</span></span>
<span class="line"><span>├── AGENTS.md</span></span>
<span class="line"><span>├── .cursor/</span></span>
<span class="line"><span>│   └── rules/</span></span>
<span class="line"><span>│       ├── 01-project-boundaries.mdc</span></span>
<span class="line"><span>│       ├── 02-architecture.mdc</span></span>
<span class="line"><span>│       ├── 03-coding-standards.mdc</span></span>
<span class="line"><span>│       ├── 04-database.mdc</span></span>
<span class="line"><span>│       ├── 05-api-contracts.mdc</span></span>
<span class="line"><span>│       ├── 06-security.mdc</span></span>
<span class="line"><span>│       ├── 07-testing.mdc</span></span>
<span class="line"><span>│       └── 08-change-control.mdc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>以 Cursor Rules 格式为示例，其他 AI 工具应转换为各自支持的格式，不直接照搬目录和扩展名。</p><h2 id="二、通用-rules-正文" tabindex="-1">二、通用 Rules 正文 <a class="header-anchor" href="#二、通用-rules-正文" aria-label="Permalink to “二、通用 Rules 正文”">​</a></h2><h3 id="_01-·-项目边界规则" tabindex="-1">01 · 项目边界规则 <a class="header-anchor" href="#_01-·-项目边界规则" aria-label="Permalink to “01 · 项目边界规则”">​</a></h3><p>基础必备</p><p><strong>目的：防止 Agent 擅自改变项目现有技术方案、业务逻辑和修改范围。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 必须优先理解项目现有实现，不得在不了解现状时直接重构。</span></span>
<span class="line"><span>2. 必须遵循项目已确认的技术选型，不得擅自更换框架、组件或基础设施。</span></span>
<span class="line"><span>3. 不得擅自引入新的依赖、工具或第三方服务。</span></span>
<span class="line"><span>4. 修改范围必须与当前任务直接相关，不得随意修改无关文件。</span></span>
<span class="line"><span>5. 不得擅自删除已有功能、接口、字段或业务逻辑。</span></span>
<span class="line"><span>6. 发现现有设计存在问题时，应先分析影响范围，再提出调整建议。</span></span>
<span class="line"><span>7. 需求不明确、业务规则缺失或存在重大方案分歧时，必须先向用户确认。</span></span>
<span class="line"><span>8. 不得将推测的业务规则当作已经确认的项目事实。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_02-·-架构与模块边界规则" tabindex="-1">02 · 架构与模块边界规则 <a class="header-anchor" href="#_02-·-架构与模块边界规则" aria-label="Permalink to “02 · 架构与模块边界规则”">​</a></h3><p><strong>目的：保证项目架构一致，防止模块职责混乱和不合理耦合。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 必须遵循项目现有架构和模块职责划分。</span></span>
<span class="line"><span>2. 不得绕过既定模块边界直接访问其他模块内部实现。</span></span>
<span class="line"><span>3. 模块之间的交互必须遵循项目已有接口和依赖约定。</span></span>
<span class="line"><span>4. 不得随意增加跨模块依赖或形成循环依赖。</span></span>
<span class="line"><span>5. 公共组件、基础设施和核心业务模块的修改必须评估影响范围。</span></span>
<span class="line"><span>6. 不得为了少量代码复用而引入过度抽象。</span></span>
<span class="line"><span>7. 新增功能应优先复用现有架构和公共能力。</span></span>
<span class="line"><span>8. 涉及架构调整时，必须明确调整原因、影响范围和兼容性。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_03-·-编码规范规则" tabindex="-1">03 · 编码规范规则 <a class="header-anchor" href="#_03-·-编码规范规则" aria-label="Permalink to “03 · 编码规范规则”">​</a></h3><p><strong>目的：保证代码可读、可维护，并与现有项目风格一致。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 必须遵循项目现有命名规范、目录结构和代码风格。</span></span>
<span class="line"><span>2. 新增代码必须保持职责清晰，避免单个类、函数或模块承担过多职责。</span></span>
<span class="line"><span>3. 不得重复实现项目中已经存在的公共能力。</span></span>
<span class="line"><span>4. 不得保留无用代码、无意义注释、调试代码和临时实现。</span></span>
<span class="line"><span>5. 不得使用空异常捕获、无意义默认值或静默忽略错误的方式掩盖问题。</span></span>
<span class="line"><span>6. 异常处理必须明确，不能随意吞掉异常信息。</span></span>
<span class="line"><span>7. 不得通过硬编码敏感信息、环境配置或易变业务参数解决问题。</span></span>
<span class="line"><span>8. 注释应解释必要的业务规则、复杂逻辑和设计原因，不重复描述代码本身。</span></span>
<span class="line"><span>9. 不得为了形式上的代码整洁而擅自扩大重构范围。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_04-·-数据库与数据操作规则" tabindex="-1">04 · 数据库与数据操作规则 <a class="header-anchor" href="#_04-·-数据库与数据操作规则" aria-label="Permalink to “04 · 数据库与数据操作规则”">​</a></h3><p>基础必备</p><p><strong>目的：保护数据完整性，避免不安全的数据操作。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 必须遵循项目现有数据库类型、命名规范和数据访问方式。</span></span>
<span class="line"><span>2. 不得擅自修改已有表结构、字段类型、索引或约束。</span></span>
<span class="line"><span>3. 数据库结构变更必须提供对应的 SQL、迁移脚本或项目规定的变更交付物。</span></span>
<span class="line"><span>4. 不得在未经确认的情况下执行生产环境数据修改、删除或清理操作。</span></span>
<span class="line"><span>5. 涉及批量更新、批量删除和数据迁移时，必须评估影响范围。</span></span>
<span class="line"><span>6. 涉及事务的业务操作必须遵循项目事务管理约定。</span></span>
<span class="line"><span>7. 不得绕过项目既定的数据访问层和业务校验机制。</span></span>
<span class="line"><span>8. 必须关注数据一致性、唯一性、关联关系和并发问题。</span></span>
<span class="line"><span>9. 不得在代码、日志或提交文件中暴露真实敏感数据。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_05-·-接口与数据交互规则" tabindex="-1">05 · 接口与数据交互规则 <a class="header-anchor" href="#_05-·-接口与数据交互规则" aria-label="Permalink to “05 · 接口与数据交互规则”">​</a></h3><p><strong>目的：保证接口契约稳定，避免前后端及模块之间的数据交互不一致。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 必须遵循项目现有接口命名、请求方式和数据结构规范。</span></span>
<span class="line"><span>2. 不得擅自修改已有接口的请求参数、响应结构和字段含义。</span></span>
<span class="line"><span>3. 接口变更必须检查调用方及关联模块的兼容性。</span></span>
<span class="line"><span>4. 必须明确必要的参数校验、异常处理和错误返回。</span></span>
<span class="line"><span>5. 不得将数据库实体直接暴露给外部接口，除非项目明确采用该设计。</span></span>
<span class="line"><span>6. 前后端必须遵循统一的数据类型、字段命名和状态约定。</span></span>
<span class="line"><span>7. 不得使用未经确认的模拟数据代替真实业务数据。</span></span>
<span class="line"><span>8. 涉及公共接口时，必须考虑已有调用方的兼容性。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_06-·-安全规则" tabindex="-1">06 · 安全规则 <a class="header-anchor" href="#_06-·-安全规则" aria-label="Permalink to “06 · 安全规则”">​</a></h3><p>基础必备</p><p><strong>目的：防止敏感信息泄露、越权操作和不安全的代码实现。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 禁止在代码仓库中提交密码、密钥、访问令牌和其他敏感凭证。</span></span>
<span class="line"><span>2. 敏感配置必须通过项目规定的安全配置方式管理。</span></span>
<span class="line"><span>3. 必须关注身份认证、权限校验和数据访问控制。</span></span>
<span class="line"><span>4. 不得仅依赖前端权限控制保护后端接口。</span></span>
<span class="line"><span>5. 涉及用户输入时，必须关注 SQL 注入、脚本注入和非法参数风险。</span></span>
<span class="line"><span>6. 不得绕过项目已有的认证、授权和审计机制。</span></span>
<span class="line"><span>7. 不得将敏感业务数据、用户隐私或凭证写入普通日志。</span></span>
<span class="line"><span>8. 执行外部命令、文件操作和网络请求时，必须考虑输入校验及操作范围。</span></span>
<span class="line"><span>9. 未经授权，不得访问、导出或传播项目中的敏感数据。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_07-·-测试与质量规则" tabindex="-1">07 · 测试与质量规则 <a class="header-anchor" href="#_07-·-测试与质量规则" aria-label="Permalink to “07 · 测试与质量规则”">​</a></h3><p><strong>目的：确保代码修改经过必要验证，而不是仅仅完成代码编写。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 新增或修改功能必须根据影响范围执行相应测试。</span></span>
<span class="line"><span>2. 修改已有功能时，必须关注相关功能是否受到影响。</span></span>
<span class="line"><span>3. 修复缺陷时，优先补充能够覆盖问题的测试。</span></span>
<span class="line"><span>4. 不得通过删除测试、跳过断言或修改测试预期来掩盖问题。</span></span>
<span class="line"><span>5. 测试失败时，必须分析原因并如实报告。</span></span>
<span class="line"><span>6. 不得将未执行的测试标记为通过。</span></span>
<span class="line"><span>7. 不得将编译成功等同于功能正确。</span></span>
<span class="line"><span>8. 对核心业务逻辑、异常场景和边界条件应进行必要验证。</span></span>
<span class="line"><span>9. 不得隐瞒已知缺陷、测试失败和未完成事项。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_08-·-变更与操作控制规则" tabindex="-1">08 · 变更与操作控制规则 <a class="header-anchor" href="#_08-·-变更与操作控制规则" aria-label="Permalink to “08 · 变更与操作控制规则”">​</a></h3><p><strong>目的：保护用户已有工作，避免未经授权的修改和不可逆操作。</strong></p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 修改前必须检查当前工作区状态。</span></span>
<span class="line"><span>2. 不得擅自覆盖、删除或回滚用户已有修改。</span></span>
<span class="line"><span>3. 不得擅自执行 Git reset --hard、强制推送等高风险操作。</span></span>
<span class="line"><span>4. 不得擅自删除分支、提交历史或其他任务的工作成果。</span></span>
<span class="line"><span>5. 不得擅自执行生产环境部署、数据清理和不可逆操作。</span></span>
<span class="line"><span>6. 涉及批量文件修改时，必须确认修改范围。</span></span>
<span class="line"><span>7. 不得擅自修改与当前任务无关的环境配置。</span></span>
<span class="line"><span>8. Git 提交必须遵循项目提交约定，未经用户要求不得擅自推送远程。</span></span>
<span class="line"><span>9. 完成任务后，应能够说明实际修改内容和变更范围。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="三、使用分档" tabindex="-1">三、使用分档 <a class="header-anchor" href="#三、使用分档" aria-label="Permalink to “三、使用分档”">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>规则</th><th>建议</th></tr></thead><tbody><tr><td>核心基础规则</td><td>项目边界、数据库、安全、变更控制</td><td>所有项目优先建立</td></tr><tr><td>按需规则</td><td>架构、编码、接口、测试</td><td>根据项目技术和业务特点完善</td></tr></tbody></table><h2 id="四、与-agents-md、skills-的关系" tabindex="-1">四、与 AGENTS.md、Skills 的关系 <a class="header-anchor" href="#四、与-agents-md、skills-的关系" aria-label="Permalink to “四、与 AGENTS.md、Skills 的关系”">​</a></h2><ul><li><strong>AGENTS.md</strong>：项目入口，说明项目情况、协作约定和规则索引。</li><li><strong>Rules</strong>：行为约束，规定必须遵守什么、禁止做什么。</li><li><strong>Skills</strong>：执行方法，告诉 Agent 一项具体工作应该怎么做。</li></ul><p>例如：未经授权禁止修改生产数据库是 Rule；数据库结构变更与迁移流程是 Skill；告诉 Agent 二者位置的是 AGENTS.md。</p><h2 id="五、使用约束" tabindex="-1">五、使用约束 <a class="header-anchor" href="#五、使用约束" aria-label="Permalink to “五、使用约束”">​</a></h2><ol><li>按适用范围加载，不把所有规则设为全局强制。</li><li>不为规则数量而增加规则，一条能明确约束就不必拆成多条。</li><li>规则必须与工具加载机制匹配，确保 Agent 实际加载。</li></ol><p>先把八类作为通用规则库，按项目现状选用适用规则，再补充项目特有约束。</p>`,42)])])}const o=n(l,[["render",i]]);export{u as __pageData,o as default};
